async function boot(){try{[state.data,state.documents]=await Promise.all([fetch('./data/index.json').then(response=>{if(!response.ok)throw new Error('index unavailable');return response.json()}),fetch('./data/documents.json').then(response=>{if(!response.ok)throw new Error('document manifest unavailable');return response.json()})]);try{state.conceptQueue=loadQueue(localStorage,state.data);state.data.local_senses=approvedLocalSenses(state.conceptQueue,state.data)}catch(error){state.conceptQueue=emptyQueue();state.data.local_senses=[];toast(`Concept queue could not load: ${error.message}`)}$('serviceStatus').textContent='Canonical browser engine ready';document.querySelector('.status-dot').classList.add('ready');document.querySelector('.principles dl').innerHTML=`<div><dt>${state.data.counts.atoms}</dt><dd>canonical atoms</dd></div><div><dt>${state.data.counts.compounds}</dt><dd>approved compounds</dd></div><div><dt>${state.data.counts.senses}</dt><dd>indexed senses</dd></div><div><dt>${state.data.counts.gaps}</dt><dd>visible gaps</dd></div>`;renderRootJump();renderCatalog();renderDocuments();renderLorePresetPicker();renderConceptQueue()}catch(error){$('serviceStatus').textContent='Engine unavailable';showError({code:'load_failed',message:'The canonical browser data or document manifest could not be loaded.'})}}
function setAppView(next,button){state.view=next;document.querySelectorAll('[data-app-view]').forEach(section=>section.classList.toggle('view-hidden',section.dataset.appView!==next));document.querySelectorAll('.app-tab').forEach(tab=>{tab.classList.toggle('active',tab===button);tab.setAttribute('aria-selected',tab===button)});window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.app-tab').forEach(button=>button.addEventListener('click',()=>setAppView(button.dataset.appTab,button)));
function setMode(next,button){if(next===state.mode)return;state.drafts[state.mode]=$('sourceInput').value;state.mode=next;$('sourceInput').value=state.drafts[next];state.analysis=null;state.selected=null;state.resolution=null;$('results').classList.add('hidden');$('output').classList.add('hidden');document.querySelectorAll('.mode-tab').forEach(x=>{x.classList.toggle('active',x===button);x.setAttribute('aria-selected',x===button)});$('inputLabel').textContent=next==='general'?'Write it in normal English':'Enter canonical controlled English';$('sourceInput').placeholder=next==='general'?'Try: I need food.':'Try: QUESTION "active destination" [1].';$('inputHint').textContent=next==='general'?'Any phrase may be analyzed. Known meanings translate; unfamiliar nouns may use sound labels, while unknown verbs and descriptors remain visible gaps.':'Advanced mode accepts exact canonical statements.';$('analyzeButton').innerHTML=next==='general'?'Translate English <span>→</span>':'Compile statement <span>→</span>';document.querySelectorAll('[data-example]').forEach((x,i)=>{x.textContent=examples[next][i][0];x.dataset.example=examples[next][i][1]})}
