async function sentenceTemplate(target){return state.data.compound_plans?.[target]?.expanded.nodes.some(node=>node.kind==='slot')?{authority:state.data}:{...(await resolutionDocument(target)).variants['assertion:1'],authority:state.data}}
async function analyze(){const input=$('sourceInput').value.trim();if(!input)return toast('Write something in English to translate.');$('analyzeButton').disabled=true;try{if(state.mode==='controlled')await compileControlled(input);else{const groupPlan=clauseInterpretationPlan(input);if(groupPlan?.clauses.some(({parsed})=>parsed.requiredViewpoint||parsed.requiredDestination||parsed.requiredInterpretation)){showClauseInterpretations(input,groupPlan);return}if(parseNamedSentence(input)?.requiredViewpoint){showCarryingViewpoint(input);return}if(parseNamedSentence(input)?.requiredDestination){showCarryingViewpoint(input);return}if(['thermal_standard','mass_standard'].includes(parseNamedSentence(input)?.requiredInterpretation)){showAdjectiveStandard(input);return}if(parseNamedSentence(input)?.requiredInterpretation){showFutureInterpretation(input);return}if(parseSentenceConditional(input)||parseNamedSentence(input)||parseSentenceSequence(input)||parseSentenceConjunction(input)){const composed=parseSentenceConditional(input)?await composeSentenceConditional(input,sentenceTemplate):parseSentenceConjunction(input)?await composeSentenceConjunction(input,sentenceTemplate):parseSentenceSequence(input)?await composeSentenceSequence(input,sentenceTemplate):await composeNamedSentence(input,await sentenceTemplate(parseNamedSentence(input).predicate));state.analysis=null;state.selected=null;state.phraseNames=[];state.resolution=composed;$('results').classList.add('hidden');await showResolution(composed,{definition:[composed.interpretation,composed.semantic_note].filter(Boolean).join(' ')});return}const result=analyzeEnglish(input,state.data);if(needsSentenceComposition(input)){result.decision.auto_resolution_allowed=false;result.decision.requires_clarification=true;result.decision.reasons.push('incomplete_sentence_construction');result.complete_sentence_unavailable=true}showAnalysis(result);if(result.decision.auto_resolution_allowed){const first=$('candidateList').querySelector('.candidate');selectCandidate(0,first);$('resolutionPrompt').textContent=`Automatically selected ${state.selected.sense_id}. The dictionary reading is ready below; choose another option only if you meant something else.`;await resolveSelected(true)}}}catch(error){showError(error)}finally{$('analyzeButton').disabled=false}}
function showClauseInterpretations(input,plan){
  state.analysis=null;state.selected=null;state.resolution=null;state.phraseNames=[];state.wordSelections.clear();
  $('output').classList.add('hidden');$('phraseCoverage').classList.add('hidden');$('resolutionPanel').classList.add('hidden');$('results').classList.remove('hidden');$('candidateList').innerHTML='';
  $('decisionSummary').textContent='Choose the meanings for each clause. Each choice applies only to the clause shown above it.';
  const card=document.createElement('article');card.className='candidate';
  const read=[];
  const select=(section,label,options)=>{const wrap=document.createElement('label');wrap.textContent=label;const field=document.createElement('select');for(const [value,text] of options){const option=document.createElement('option');option.value=value;option.textContent=text;field.append(option)}field.value=options[0][0];wrap.append(field);section.append(wrap);return field};
  plan.clauses.forEach(({text,parsed},index)=>{
    const section=document.createElement('fieldset'),title=document.createElement('legend');title.textContent=`Clause ${index+1}: ${text}`;section.append(title);
    let view,destination,interpretation,threshold,scale;
    if(parsed.requiredViewpoint)view=select(section,`Clause ${index+1} carrying meaning`,[['','Choose a meaning'],['habitual','A recurring practice'],['ongoing','An unfolding action'],['bounded','One narrated episode']]);
    if(parsed.requiredDestination){destination=select(section,`Clause ${index+1} meaning of to`,[['','Choose a destination meaning'],['spatial','Spatial destination; no receipt asserted']]);const note=document.createElement('p');note.textContent='Receipt and delivery to a recipient need a different meaning, which is not implemented yet.';section.append(note)}
    const property=['mass_standard','thermal_standard'].includes(parsed.requiredInterpretation);
    if(property){
      const mass=parsed.requiredInterpretation==='mass_standard',note=document.createElement('p');note.textContent=`For “${parsed.adjective}”, use ${mass?'mass':'thermodynamic temperature'} ${['heavy','hot'].includes(parsed.adjective)?'above':'below'} this clause’s threshold.`;section.append(note);
      const label=document.createElement('label');label.textContent=`Clause ${index+1} ${mass?'mass':'temperature'} threshold`;threshold=document.createElement('input');threshold.type='text';threshold.inputMode='decimal';threshold.maxLength=1000;threshold.placeholder='Enter your contextual threshold';label.append(threshold);section.append(label);
      scale=select(section,`Clause ${index+1} ${mass?'mass unit':'temperature scale'}`,mass?[['kilogram','Kilograms'],['gram','Grams']]:[['celsius','Degrees Celsius'],['kelvin','Kelvins']]);
    }else if(parsed.requiredInterpretation==='future_assertion')interpretation=select(section,`Clause ${index+1} future meaning`,[['','Choose a future meaning'],['future_assertion','Future statement; no promise or intention added']]);
    if(!view&&!destination&&!property&&!interpretation){const note=document.createElement('p');note.textContent='No additional interpretation choice is needed for this clause.';section.append(note)}
    read.push(()=>({...view?{viewpoint:view.value}:{},...destination?{destination:destination.value}:{},...property?{interpretation:parsed.requiredInterpretation,standard:{dimension:parsed.requiredInterpretation==='mass_standard'?'mass':'thermodynamic_temperature',threshold:threshold.value.trim(),scale:scale.value}}:interpretation?{interpretation:interpretation.value}:{}}));
    card.append(section);
  });
  const status=document.createElement('p');status.setAttribute('role','status');const button=document.createElement('button');button.textContent='Translate all clauses';
  button.addEventListener('click',async()=>{
    if(card.isConnected===false||$('sourceInput').value.trim()!==input||state.mode==='controlled')return;
    const choices=read.map(get=>get()),snapshot=JSON.stringify(choices),current=()=>card.isConnected!==false&&$('sourceInput').value.trim()===input&&state.mode!=='controlled'&&JSON.stringify(read.map(get=>get()))===snapshot;
    button.disabled=true;status.textContent='';
    try{
      const compose=({conditional:composeSentenceConditional,sequence:composeSentenceSequence,all_of:composeSentenceConjunction})[plan.operator];
      const result=await compose(input,sentenceTemplate,choices);if(!current())return;
      state.resolution=result;$('results').classList.add('hidden');await showResolution(result,{definition:[result.interpretation,result.semantic_note].filter(Boolean).join(' ')});
    }catch(error){if(current())status.textContent=error.message}finally{button.disabled=false}
  });
  card.append(status,button);$('candidateList').append(card);$('results').scrollIntoView({behavior:'smooth',block:'start'});
}
function showCarryingViewpoint(input){
  const parsed=parseNamedSentence(input),needsMass=parsed.requiredInterpretation==='mass_standard';
  state.analysis=null;state.selected=null;state.resolution=null;state.phraseNames=[];state.wordSelections.clear();
  $('output').classList.add('hidden');$('phraseCoverage').classList.add('hidden');$('resolutionPanel').classList.add('hidden');$('results').classList.remove('hidden');$('candidateList').innerHTML='';
  $('decisionSummary').textContent='Choose the intended carrying meaning before generating sound.';
  const card=document.createElement('article');card.className='candidate';
  const description=document.createElement('p');description.textContent=parsed.requiredDestination?'A spatial destination is different from a recipient. An unfolding action does not assert arrival; completed destination-carrying reaches its endpoint. Receipt and delivery meanings are not implemented yet.':'A recurring practice, an unfolding action and one narrated episode have different meanings. None automatically means arrival, delivery or a future plan.';
  const viewpointLabel=document.createElement('label');viewpointLabel.textContent='Carrying meaning';
  const viewpoint=document.createElement('select');
  for(const [value,text] of [['','Choose a meaning'],['habitual','A recurring practice'],['ongoing','An unfolding action'],['bounded','One narrated episode']]){const option=document.createElement('option');option.value=value;option.textContent=text;viewpoint.append(option)}
  viewpoint.value='';viewpointLabel.append(viewpoint);card.append(description);if(parsed.requiredViewpoint)card.append(viewpointLabel);
  let destination;
  if(parsed.requiredDestination){
    const label=document.createElement('label');label.textContent='Meaning of to';destination=document.createElement('select');
    for(const [value,text] of [['','Choose a destination meaning'],['spatial','Spatial destination; no receipt asserted']]){const option=document.createElement('option');option.value=value;option.textContent=text;destination.append(option)}
    destination.value='';label.append(destination);card.append(label);
  }
  let threshold,scale;
  if(needsMass){
    const explanation=document.createElement('p');explanation.textContent=`Also choose the mass standard for “${parsed.adjective}”: ${parsed.adjective==='heavy'?'above':'below'} your threshold. Weight force, effort and brightness need different meanings.`;
    const thresholdLabel=document.createElement('label');thresholdLabel.textContent='Mass threshold';threshold=document.createElement('input');threshold.type='text';threshold.inputMode='decimal';threshold.maxLength=1000;threshold.placeholder='Enter your contextual threshold';thresholdLabel.append(threshold);
    const scaleLabel=document.createElement('label');scaleLabel.textContent='Mass unit';scale=document.createElement('select');for(const [value,text] of [['kilogram','Kilograms'],['gram','Grams']]){const option=document.createElement('option');option.value=value;option.textContent=text;scale.append(option)}scale.value='kilogram';scaleLabel.append(scale);
    card.append(explanation,thresholdLabel,scaleLabel);
  }
  const status=document.createElement('p');status.setAttribute('role','status');
  const button=document.createElement('button');button.textContent='Translate with these meanings';
  button.addEventListener('click',async()=>{
    if(card.isConnected===false||$('sourceInput').value.trim()!==input||state.mode==='controlled')return;
    const chosen=viewpoint.value,chosenDestination=destination?.value,standard=needsMass?{dimension:'mass',threshold:threshold.value.trim(),scale:scale.value}:undefined;
    const current=()=>card.isConnected!==false&&$('sourceInput').value.trim()===input&&state.mode!=='controlled'&&viewpoint.value===chosen&&destination?.value===chosenDestination&&(!needsMass||(threshold.value.trim()===standard.threshold&&scale.value===standard.scale));
    button.disabled=true;status.textContent='';
    try{
      const composed=await composeNamedSentence(input,await sentenceTemplate(parsed.predicate),{...(parsed.requiredViewpoint?{viewpoint:chosen}:{}),...(parsed.requiredDestination?{destination:chosenDestination}:{}),...(needsMass?{interpretation:'mass_standard',standard}:{})});
      if(!current())return;
      state.resolution=composed;$('results').classList.add('hidden');
      await showResolution(composed,{definition:[composed.interpretation,composed.semantic_note].filter(Boolean).join(' ')});
    }catch(error){if(current())status.textContent=error.message}finally{button.disabled=false}
  });
  card.append(status,button);$('candidateList').append(card);$('results').scrollIntoView({behavior:'smooth',block:'start'});
}
function showAdjectiveStandard(input){
  const parsed=parseNamedSentence(input),massStandard=parsed.requiredInterpretation==='mass_standard',property=massStandard?'mass':'temperature';
  state.analysis=null;state.selected=null;state.resolution=null;state.phraseNames=[];state.wordSelections.clear();
  $('output').classList.add('hidden');$('phraseCoverage').classList.add('hidden');$('resolutionPanel').classList.add('hidden');$('results').classList.remove('hidden');$('candidateList').innerHTML='';
  $('decisionSummary').textContent=`What ${property} standard do you mean by “${parsed.adjective}”?`;
  const card=document.createElement('article');card.className='candidate';
  const description=document.createElement('p');description.textContent=`For this translation, use ${massStandard?'mass':'thermodynamic temperature'} ${['hot','heavy'].includes(parsed.adjective)?'above':'below'} your threshold. ${massStandard?'Weight force, carrying effort, size and brightness':'Felt warmth, spiciness and emotional meanings'} need a different interpretation.`;
  const label=document.createElement('label');label.textContent=massStandard?'Mass threshold':'Temperature threshold';
  const threshold=document.createElement('input');threshold.type='text';threshold.inputMode='decimal';threshold.maxLength=1000;threshold.placeholder='Enter your contextual threshold';label.append(threshold);
  const scaleLabel=document.createElement('label');scaleLabel.textContent=massStandard?'Mass unit':'Temperature scale';
  const scale=document.createElement('select');for(const [value,text] of (massStandard?[['kilogram','Kilograms'],['gram','Grams']]:[['celsius','Degrees Celsius'],['kelvin','Kelvins']])){const option=document.createElement('option');option.value=value;option.textContent=text;scale.append(option)}scale.value=massStandard?'kilogram':'celsius';scaleLabel.append(scale);
  const status=document.createElement('p');status.setAttribute('role','status');
  const button=document.createElement('button');button.textContent=`Use this ${property} standard`;
  button.addEventListener('click',async()=>{
    if($('sourceInput').value.trim()!==input||state.mode==='controlled'){toast('The input changed. Analyze it again.');return}
    button.disabled=true;status.textContent='';
    const chosen={dimension:massStandard?'mass':'thermodynamic_temperature',threshold:threshold.value.trim(),scale:scale.value};
    try{
      const composed=await composeNamedSentence(input,await sentenceTemplate(parsed.predicate),{interpretation:parsed.requiredInterpretation,standard:chosen});
      if($('sourceInput').value.trim()!==input||state.mode==='controlled'){toast('The input changed. Analyze it again.');return}
      if(card.isConnected===false||threshold.value.trim()!==chosen.threshold||scale.value!==chosen.scale){toast('The property standard changed. Select it again.');return}
      state.resolution=composed;$('results').classList.add('hidden');
      await showResolution(composed,{definition:[composed.interpretation,composed.semantic_note].filter(Boolean).join(' ')});
    }catch(error){status.textContent=error.message}finally{button.disabled=false}
  });
  card.append(description,label,scaleLabel,status,button);$('candidateList').append(card);$('results').scrollIntoView({behavior:'smooth',block:'start'});
}
function showFutureInterpretation(input){
  state.analysis=null;state.selected=null;state.resolution=null;state.phraseNames=[];
  state.wordSelections.clear();$('phraseCoverage').classList.add('hidden');
  $('output').classList.add('hidden');$('results').classList.remove('hidden');$('resolutionPanel').classList.add('hidden');
  $('decisionSummary').textContent='“Will” can state a future event or express a commitment. Choose the intended reading before generating sound.';
  $('candidateList').innerHTML='';
  const card=document.createElement('article');card.className='candidate';
  const description=document.createElement('p');description.textContent='Translate this as a statement about tomorrow, without adding a promise, intention, or willingness. If you meant one of those, edit the sentence; that meaning is not yet supported by this construction.';
  const button=document.createElement('button');button.textContent='Translate as a future statement';
  button.addEventListener('click',async()=>{
    if($('sourceInput').value.trim()!==input||state.mode==='controlled'){toast('The input changed. Analyze it again.');return}
    if(card.isConnected===false)return;
    button.disabled=true;
    try{
      const parsed=parseNamedSentence(input);
      const composed=await composeNamedSentence(input,await sentenceTemplate(parsed.predicate),{interpretation:'future_assertion'});
      if($('sourceInput').value.trim()!==input||state.mode==='controlled'){toast('The input changed. Analyze it again.');return}
      if(card.isConnected===false)return;
      state.resolution=composed;$('results').classList.add('hidden');
      await showResolution(composed,{definition:[composed.interpretation,composed.semantic_note].filter(Boolean).join(' ')});
    }catch(error){if(card.isConnected!==false&&$('sourceInput').value.trim()===input&&state.mode!=='controlled')showError(error)}finally{button.disabled=false}
  });
  card.append(description,button);$('candidateList').append(card);$('results').scrollIntoView({behavior:'smooth',block:'start'});
}
function showAnalysis(result){state.analysis=result;state.selected=null;state.resolution=null;state.phraseNames=[];$('results').classList.remove('hidden');$('output').classList.add('hidden');$('candidateList').innerHTML='';const names={incomplete_sentence_construction:'this sentence contains meaning the current construction cannot yet preserve; dictionary readings below are partial',material_sense_ambiguity:'please choose the intended meaning',required_roles_missing:'more details are needed',structural_template_required:'full sentence structure is not implemented yet',documented_vocabulary_gap:'this meaning is not in Era Zero yet',low_confidence_english:'I am not confident enough to guess',local_api_required:'the full local engine is required',phonemic_labels_present:'nouns were preserved as sound labels',phonemic_labels_only:'no approved semantic reading; noun-label sounds are available',unresolved_semantic_content:'an unknown verb or descriptor still needs meaning',cross_domain_action_underspecified:'file change or movement needs its intended domain'};$('decisionSummary').textContent=result.decision.auto_resolution_allowed?`Dictionary label matched${result.candidates[0]?.fidelity==='generalized'?' through a disclosed generalization':''} · ${result.runtime_inference}.`:`${result.candidate_count} interpretation${result.candidate_count===1?'':'s'} · ${result.decision.reasons.map(x=>names[x]||x).join(' · ')}`;$('speechAct').value=result.speech_act_proposal;$('runtimeState').value=result.explicit_runtime_state;$('resolutionPanel').classList.toggle('hidden',!result.candidates.length);result.candidates.forEach((candidate,index)=>{const el=document.createElement('article');el.className='candidate';el.tabIndex=0;el.innerHTML=`<div class="candidate-head"><span class="route">${escapeHtml(candidate.route)}</span><h3>${escapeHtml(candidate.lemma)} <small>${escapeHtml(candidate.sense_key.replaceAll('_',' '))}</small></h3><span class="confidence">${escapeHtml(candidate.confidence)}</span><span class="score">${candidate.score.toFixed(2)}</span></div><p>${escapeHtml(candidate.definition)}</p>${candidate.generalization?`<p class="word-definition"><b>Generalization:</b> ${escapeHtml(candidate.generalization)}</p>`:''}<div class="evidence">${candidate.target_id?escapeHtml(candidate.target_id)+' · ':''}${escapeHtml(candidate.match_type.replaceAll('_',' '))}${candidate.fidelity==='generalized'?' · generalized':''}</div>`;el.addEventListener('click',()=>selectCandidate(index,el));el.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectCandidate(index,el)}});$('candidateList').append(el)});renderPhraseCoverage(result);$('results').scrollIntoView({behavior:'smooth',block:'start'})}
function updateSentenceMap(coverage){const summary=$('sentenceMap');if(!summary)return;summary.textContent=coverage.map(item=>{if(item.status==='function_word')return`${item.term} → English syntax`;if(item.status==='participant_reference')return`${item.term} → ${item.participant_role}`;if(item.status==='unresolved_semantic')return`${item.term} → unresolved ${item.semantic_kind||'meaning'}`;if(['phonemic_label','labeled_entity'].includes(item.status))return`${item.term} → ${item.semantic_class_target_id?item.semantic_class_target_id+' + ':''}${item.name_id||'EZNAME label'}`;const selected=item.matches.find(match=>match.sense_id===state.wordSelections.get(item.token_index))||item.matches[0];return`${item.term} → ${selected?.target_id||selected?.sense_id||selected?.route||'unresolved'}${item.name_id?' + '+item.name_id:''}`}).join('  ·  ')}
function matchOptionLabel(match){const record=dictionaryRecord(match),id=match.target_id||match.route,title=record?.title||record?.display_title||match.lemma,meaning=record?.core_definition||record?.invariant_definition||match.definition||'';return`${id} — ${title} — ${meaning}`}
async function renderPhraseCoverage(result){const box=$('phraseCoverage'),coverage=result.term_coverage||[];state.wordSelections.clear();if(!coverage.length){box.classList.add('hidden');return}box.classList.remove('hidden');box.innerHTML='<div class="word-map-head"><div><h3>How each word is handled</h3><p>Verbs and descriptors require meaning. Nouns may keep a phonemic label when their detailed class is absent.</p></div></div><div class="phrase-terms word-map"></div><p id="sentenceMap" class="sentence-map"></p>';const list=box.querySelector('.phrase-terms');for(const item of coverage){const card=document.createElement('div');card.className='phrase-term';const recommended=item.matches.find(match=>match.sense_id===item.recommended_sense_id)||item.matches[0],labelAllowed=['phonemic_label','labeled_entity'].includes(item.status)||(item.status==='documented_gap'&&recommended?.noun_label_allowed);if(labelAllowed){try{const encoded=await encodeName(item.term);item.name_id=encoded.name_id;state.phraseNames.push(encoded);const explanation=item.status==='labeled_entity'?`labeled person/entity${item.semantic_class_target_id?' · class '+item.semantic_class_target_id:''}`:item.status==='documented_gap'?'documented noun gap · referent preserved as a label':'unfamiliar noun/referent · phonemic label';card.innerHTML=`<b>${escapeHtml(item.term)}</b><span>${escapeHtml(explanation)}</span><code>${escapeHtml(encoded.name_id)}</code>${recommended?.definition?`<p class="word-definition">${escapeHtml(recommended.definition)}</p>`:''}<button>▶ Hear label</button>`;card.querySelector('button').addEventListener('click',event=>playName(encoded,event.currentTarget))}catch(error){card.innerHTML=`<b>${escapeHtml(item.term)}</b><span>unencodable noun label</span>`}}else if(item.status==='participant_reference'){card.innerHTML=`<b>${escapeHtml(item.term)}</b><span>participant reference · ${escapeHtml(item.participant_role)}</span><p class="word-definition">Handled as a discourse participant, not as a phonemic name or lexical root.</p>`}else if(item.status==='unresolved_semantic'){card.innerHTML=`<b>${escapeHtml(item.term)}</b><span>unresolved ${escapeHtml(item.semantic_kind||'semantic content')} · translation blocked</span><p class="word-definition">This word carries meaning and cannot honestly be replaced by phoneme tones.</p>`}else if(item.status==='function_word'){card.innerHTML=`<b>${escapeHtml(item.term)}</b><span>English syntax/function word · no atomic meaning asserted</span><p class="word-definition">Handled by English parsing unless a later grammar template explicitly represents it.</p>`}else{const route=item.status==='documented_gap'?'documented vocabulary gap':item.status==='structural'?'structural language route':'approved semantic coverage';state.wordSelections.set(item.token_index,recommended?.sense_id);card.innerHTML=`<b>${escapeHtml(item.term)}</b><i class="recommended">best match</i><span>${escapeHtml(route)} · ${item.matches.length} option${item.matches.length===1?'':'s'}</span><label>Meaning match<select aria-label="Meaning match for ${escapeHtml(item.term)}">${item.matches.map(match=>`<option value="${escapeHtml(match.sense_id)}"${match.sense_id===recommended?.sense_id?' selected':''}>${escapeHtml(matchOptionLabel(match))}</option>`).join('')}</select></label><div class="word-target">${escapeHtml(recommended?.target_id||recommended?.sense_id||'')}</div><p class="word-definition">${escapeHtml(recommended?.definition||'')}${recommended?.generalization?` Generalization: ${escapeHtml(recommended.generalization)}`:''}</p><button class="word-dictionary">View dictionary record</button>`;const select=card.querySelector('select'),target=card.querySelector('.word-target'),definition=card.querySelector('.word-definition'),dictionary=card.querySelector('.word-dictionary');const refresh=()=>{const selected=item.matches.find(match=>match.sense_id===select.value);state.wordSelections.set(item.token_index,select.value);target.textContent=selected?.target_id||selected?.sense_id||'';definition.textContent=`${selected?.definition||''}${selected?.generalization?` Generalization: ${selected.generalization}`:''}`;dictionary.onclick=()=>openDictionarySense(selected);updateSentenceMap(coverage)};select.addEventListener('change',refresh);refresh()}list.append(card)}if(state.phraseNames.length){const hear=document.createElement('button');hear.className='primary phrase-hear';hear.textContent=state.phraseNames.length===coverage.filter(item=>!['function_word','participant_reference'].includes(item.status)).length?'▶ Hear complete label-only phrase':'▶ Hear noun labels';hear.addEventListener('click',event=>playPhraseNames(event.currentTarget));box.append(hear)}updateSentenceMap(coverage)}
function dictionaryRecord(sense){if(sense.route==='atom')return state.data.atoms.find(atom=>atom.canonical_id===sense.target_id);if(sense.route==='compound')return state.data.compounds.find(compound=>compound.compound_id===sense.target_id);return null}
function plainRecord(targetId){return state.data.plain_english?.entries?.find(entry=>entry.target_id===targetId)||null}
function renderRootJump(){const options=[...state.data.atoms.map(atom=>({id:atom.canonical_id,title:atom.title,definition:atom.core_definition})),...state.data.compounds.map(compound=>({id:compound.compound_id,title:compound.display_title,definition:compound.invariant_definition}))].sort((a,b)=>a.id.localeCompare(b.id));$('catalogJump').innerHTML='<option value="">Choose a root or compound</option>'+options.map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(`${item.id} — ${item.title} — ${item.definition}`)}</option>`).join('')}
function showDictionaryDetail(sense,item=null){document.querySelectorAll('.catalog-item').forEach(card=>card.classList.toggle('active',card===item));const record=dictionaryRecord(sense),plain=plainRecord(sense.target_id),related=state.data.senses.filter(option=>option.target_id&&option.target_id===sense.target_id),lexical=state.data.lexical_pos_audit?.roots?.find(root=>root.target_id===sense.target_id);let details='';if(sense.route==='atom'&&record){details=`<dl><dt>Canonical ID</dt><dd><code>${escapeHtml(record.canonical_id)}</code></dd><dt>Family</dt><dd>${escapeHtml(record.family)}</dd><dt>Address</dt><dd><code>${escapeHtml(record.address)}</code></dd><dt>Universal slot</dt><dd>${escapeHtml(record.universal_slot)}</dd><dt>Semantic affordance</dt><dd>${escapeHtml(lexical?.semantic_affordance?.primary?.replaceAll('_',' ')||'')}</dd><dt>Compact root</dt><dd><code>${escapeHtml(record.local_compact_root)}</code></dd><dt>Transliteration</dt><dd><code>${escapeHtml(record.canonical_transliteration)}</code></dd><dt>Formal carrier</dt><dd><code>${escapeHtml(record.formal_carrier)}</code></dd><dt>Harmonic signature</dt><dd><code>${escapeHtml(record.harmonic_signature_semitones.join(' · '))}</code></dd><dt>Relative note path</dt><dd><code>${escapeHtml(record.note_path_semitones.join(' · '))}</code></dd><dt>Status</dt><dd>${escapeHtml(record.status)}</dd></dl>`}else if(sense.route==='compound'&&record){details=`<dl><dt>Compound ID</dt><dd><code>${escapeHtml(record.compound_id)}</code></dd><dt>Status</dt><dd>${escapeHtml(record.status)}</dd><dt>Version</dt><dd>${escapeHtml(record.definition_version)}</dd><dt>Semantic head</dt><dd><code>${escapeHtml(record.semantic_head)}</code></dd><dt>Graph nodes</dt><dd>${record.nodes.map(node=>escapeHtml(node.root_id)).join(' · ')}</dd><dt>Graph edges</dt><dd>${record.edges.map(edge=>`${escapeHtml(edge.type)}: ${escapeHtml(edge.from)} → ${escapeHtml(edge.to)}`).join('<br>')}</dd><dt>Includes</dt><dd>${escapeHtml(record.boundaries?.includes)}</dd><dt>Excludes</dt><dd>${escapeHtml(record.boundaries?.excludes)}</dd></dl>`}else{details=`<dl><dt>Sense ID</dt><dd><code>${escapeHtml(sense.sense_id)}</code></dd><dt>Route</dt><dd>${escapeHtml(sense.route)}</dd><dt>Sense key</dt><dd>${escapeHtml(sense.sense_key.replaceAll('_',' '))}</dd><dt>Part of speech</dt><dd>${escapeHtml(sense.part_of_speech||'not assigned')}</dd><dt>Controlled input</dt><dd>${sense.controlled_input_allowed?'allowed':'not a direct lexical target'}</dd></dl>`}const plainSection=plain?`<h4>Plain-English discovery</h4><p><b>${escapeHtml(plain.plain_label)}</b> — ${escapeHtml(plain.plain_explanation)}</p><p>${plain.ordinary_terms.map(term=>`<span class="route">${escapeHtml(term)}</span>`).join(' ')}</p><p class="word-definition">${escapeHtml(plain.authority_note)}</p>`:'';$('catalogDetail').innerHTML=`<p class="eyebrow">${escapeHtml(sense.route)} record</p><h3>${escapeHtml(record?.title||record?.display_title||sense.lemma)}</h3><p>${escapeHtml(record?.core_definition||record?.invariant_definition||sense.definition)}</p>${details}${plainSection}<h4>Indexed English senses</h4><ul>${(related.length?related:[sense]).map(option=>`<li><b>${escapeHtml(option.lemma)}</b> <code>${escapeHtml(option.part_of_speech||'')}</code> — ${escapeHtml(option.definition)}</li>`).join('')}</ul><p><a href="https://github.com/ragingaxolotl-art/era-zero-translator/blob/main/${sense.route==='atom'?'lexicon/all_atoms.yaml':sense.route==='compound'?'lexicon/compound_dictionary.yaml':'lexicon/english_sense_index.yaml'}" target="_blank" rel="noopener">Open machine authority ↗</a></p>`}
function renderCatalog(openSenseId=null){if(!state.data)return;const query=normalize($('catalogSearch').value),route=$('catalogRoute').value,family=$('catalogFamily').value;const matches=state.data.senses.filter(sense=>{const targetFamily=(sense.target_id||'').split(':')[0],record=dictionaryRecord(sense),plain=plainRecord(sense.target_id),haystack=normalize([sense.sense_id,sense.lemma,sense.sense_key,sense.route,sense.target_id,sense.definition,...(sense.selection_cues||[]),record?.address,record?.local_compact_root,record?.canonical_transliteration,record?.formal_carrier,plain?.plain_label,plain?.plain_explanation,...(plain?.ordinary_terms||[])].join(' '));return(!query||haystack.includes(query))&&(route==='all'||sense.route===route)&&(family==='all'||targetFamily===family)});$('catalogSummary').textContent=`Showing ${matches.length} indexed options · ${state.data.counts.atoms} roots · ${state.data.counts.compounds} compounds · ${state.data.counts.plain_language_entries} plain-English maps`;$('catalogList').innerHTML='';matches.forEach(sense=>{const plain=plainRecord(sense.target_id),item=document.createElement('article');item.className='catalog-item';item.tabIndex=0;item.dataset.senseId=sense.sense_id;item.innerHTML=`<header><span class="route">${escapeHtml(sense.route)}</span><strong>${escapeHtml(sense.lemma)}</strong></header><p>${escapeHtml(sense.definition)}</p>${plain?`<div class="word-definition"><b>Everyday:</b> ${escapeHtml(plain.plain_label)}</div>`:''}<div class="evidence">${escapeHtml(sense.target_id||sense.sense_id)} · ${escapeHtml(sense.sense_key.replaceAll('_',' '))}</div><div class="item-actions"><button class="inspect-entry">Inspect</button><button class="use-wording">Use in translator</button></div>`;const inspect=()=>showDictionaryDetail(sense,item);item.addEventListener('click',inspect);item.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();inspect()}});item.querySelector('.inspect-entry').addEventListener('click',event=>{event.stopPropagation();inspect()});item.querySelector('.use-wording').addEventListener('click',event=>{event.stopPropagation();const translatorTab=document.querySelector('[data-app-tab="translator"]');setAppView('translator',translatorTab);$('sourceInput').value=plain?.plain_label||sense.lemma;$('sourceInput').focus();analyze()});$('catalogList').append(item);if(openSenseId===sense.sense_id)showDictionaryDetail(sense,item)});if(openSenseId&&!matches.some(sense=>sense.sense_id===openSenseId))$('catalogDetail').innerHTML='<p>No dictionary record matched the current filters.</p>'}
function openDictionarySense(match){if(!match)return;const sense=state.data.senses.find(item=>item.sense_id===match.sense_id)||match,tab=document.querySelector('[data-app-tab="dictionary"]');setAppView('dictionary',tab);$('catalogSearch').value=sense.target_id||sense.lemma;$('catalogRoute').value='all';$('catalogFamily').value='all';renderCatalog(sense.sense_id)}
$('catalogSearch').addEventListener('input',renderCatalog);$('catalogRoute').addEventListener('change',renderCatalog);$('catalogFamily').addEventListener('change',renderCatalog);
$('catalogJump').addEventListener('change',event=>{if(!event.target.value)return;$('catalogSearch').value=event.target.value;$('catalogRoute').value='all';$('catalogFamily').value='all';const sense=state.data.senses.find(item=>item.target_id===event.target.value);renderCatalog(sense?.sense_id)});
function conceptRoute(result){const top=result.candidates[0],coverage=result.term_coverage||[];if(top?.route==='atom')return{route:top.match_type==='exact_lemma'?'existing_surface':'existing_atom',label:top.match_type==='exact_lemma'?'Consolidate with a reviewed English sense':'Review as a surface mapping to an existing atom',top};if(top?.route==='compound')return{route:top.match_type==='exact_lemma'?'existing_surface':'existing_compound',label:'Review against an approved compound',top};if(top?.route==='semantic_ir')return{route:'semantic_ir',label:'Route to a Semantic IR template',top};if(top?.route==='grammar')return{route:'grammar',label:'Route to grammar',top};if(top?.route==='gap')return{route:'documented_gap',label:'Keep the documented vocabulary gap visible',top};if(coverage.some(item=>item.status==='unresolved_semantic'))return{route:'semantic_review',label:'Open semantic review; do not phonemically label this predicate',top:null};return{route:'future_era',label:'Collect corpus evidence before considering a new atomic meaning',top:null}}
$('analyzeConcept').addEventListener('click',()=>{const input=$('conceptInput').value.trim(),box=$('conceptResult');if(!input)return toast('Enter a word or concept to check.');try{const result=analyzeEnglish(input,state.data,{limit:12}),decision=conceptRoute(result),proposal={format:'EZ-CONCEPT-PROPOSAL-1',status:'observed',submitted_form:input,proposed_route:decision.route,candidate_target:decision.top?.target_id||null,candidate_sense_id:decision.top?.sense_id||null,automatic_canonical_approval:false,review_required:true};box.classList.remove('hidden');box.innerHTML=`<strong>${escapeHtml(decision.label)}</strong><br>${decision.top?`${escapeHtml(decision.top.target_id||decision.top.route)} — ${escapeHtml(decision.top.lemma)} — ${escapeHtml(decision.top.definition)}`:'No existing reviewed meaning safely resolves the semantic content.'}<br><code>${escapeHtml(JSON.stringify(proposal))}</code>`}catch(error){box.classList.remove('hidden');box.textContent=error.message||'Concept analysis failed.'}});
function commitConceptQueue(next){state.conceptQueue=saveQueue(localStorage,next,state.data);state.data.local_senses=approvedLocalSenses(state.conceptQueue,state.data);renderConceptQueue();renderCatalog()}
function renderConceptQueue(){const proposals=[...state.conceptQueue.proposals].reverse();$('conceptQueueSummary').textContent=`${proposals.length} local proposal${proposals.length===1?'':'s'} · ${proposals.filter(p=>p.status==='approved').length} reviewed surface mapping${proposals.filter(p=>p.status==='approved').length===1?'':'s'} · no new canonical meanings.`;$('conceptQueue').innerHTML=proposals.map(p=>`<article class="concept-card" data-concept-id="${escapeHtml(p.proposal_id)}"><strong>${escapeHtml(p.submitted_form)}</strong> <code>${escapeHtml(p.status)}</code><p>${escapeHtml(p.intended_meaning)}</p><small>${escapeHtml(p.example_context)} · ${escapeHtml(p.proposed_part_of_speech)}</small><label>Review status<select class="concept-status"><option value="triaged">Triaged</option><option value="semantic_review">Semantic review needed</option><option value="approved">Approve local surface → existing target</option><option value="future_era">Future Era review</option><option value="rejected">Rejected</option><option value="superseded">Superseded</option></select></label><label>Existing root/compound ID<input class="concept-target" value="${escapeHtml(p.reviewed_target||p.candidate_target||'')}" placeholder="e.g. MOV:101"></label><label>Collision and neighbor audit<textarea class="concept-collisions" placeholder="Why does this meaning not collide with another target?">${escapeHtml(p.collision_notes)}</textarea></label><label>Reviewer name<input class="concept-reviewer" value="${escapeHtml(p.reviewer_name)}"></label><label>Written decision<textarea class="concept-decision" placeholder="Explain why the target entails this meaning, or why review remains open.">${escapeHtml(p.reviewer_decision)}</textarea></label><label class="concept-attestation"><input type="checkbox" class="concept-entailment"> I checked the invariant definition and exclusions; this is only a local English surface mapping.</label><button class="concept-review-save">Record review</button><small>Approval changes only this browser's English lookup. New atoms and compounds require a separate standard migration.</small></article>`).join('');for(const card of $('conceptQueue').querySelectorAll('.concept-card')){const proposal=state.conceptQueue.proposals.find(p=>p.proposal_id===card.dataset.conceptId);card.querySelector('.concept-status').value=proposal.status==='observed'?'triaged':proposal.status;card.querySelector('.concept-review-save').addEventListener('click',()=>{try{const decision={status:card.querySelector('.concept-status').value,reviewed_target:card.querySelector('.concept-target').value.toUpperCase().trim(),collision_notes:card.querySelector('.concept-collisions').value,reviewer_name:card.querySelector('.concept-reviewer').value,reviewer_decision:card.querySelector('.concept-decision').value,entailment_confirmed:card.querySelector('.concept-entailment').checked};commitConceptQueue(reviewProposal(state.conceptQueue,proposal.proposal_id,decision,state.data));toast('Local review recorded; canonical dictionary unchanged.')}catch(error){toast(error.message)}})}}
$('saveConcept').addEventListener('click',()=>{try{if(!state.data)throw new Error('Dictionary still loading.');const submitted_form=$('conceptInput').value.trim(),result=analyzeEnglish(submitted_form,state.data,{limit:12}),decision=conceptRoute(result),proposal=createProposal({submitted_form,intended_meaning:$('conceptMeaning').value,example_context:$('conceptContext').value,proposed_part_of_speech:$('conceptPos').value,candidate_routes:result.candidates.map(c=>`${c.route}:${c.target_id||c.sense_id}`),candidate_target:decision.top?.target_id});commitConceptQueue(addProposal(state.conceptQueue,proposal,state.data));toast('Proposal saved locally for review.')}catch(error){toast(error.message||'Could not save concept.')}});
$('exportConcepts').addEventListener('click',()=>download(new Blob([JSON.stringify(state.conceptQueue,null,2)],{type:'application/json'}),'era-zero-concept-review-queue.json'));
$('importConcepts').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('Review queue file is too large.');const incoming=validateQueue(JSON.parse(await file.text()),state.data),merged=new Map(state.conceptQueue.proposals.map(p=>[p.proposal_id,p]));for(const p of incoming.proposals)merged.set(p.proposal_id,p);commitConceptQueue(validateQueue({...state.conceptQueue,proposals:[...merged.values()]},state.data));toast(`Imported ${incoming.proposals.length} review records.`)}catch(error){toast(`Import failed: ${error.message}`)}finally{event.target.value=''}});
function renderDocuments(){if(!state.documents)return;const categorySelect=$('documentCategory');categorySelect.innerHTML='<option value="all">All categories</option>'+state.documents.categories.map(category=>`<option value="${escapeHtml(category)}">${escapeHtml(category)}</option>`).join('');$('documentProvenance').innerHTML=state.documents.sources.map(source=>`<article class="provenance-card"><strong>${escapeHtml(source.title)}</strong><p>${escapeHtml(source.detail)}</p><a href="${escapeHtml(source.url)}" target="_blank" rel="noopener">Open source ↗</a></article>`).join('');filterDocuments()}
function filterDocuments(){if(!state.documents)return;const query=normalize($('documentSearch').value),category=$('documentCategory').value,matches=state.documents.documents.filter(document=>{const haystack=normalize([document.title,document.path,document.category,document.format].join(' '));return(!query||haystack.includes(query))&&(category==='all'||document.category===category)});$('documentSummary').textContent=`Showing ${matches.length} of ${state.documents.count} available project records`;$('documentList').innerHTML=matches.map(document=>`<article class="document-item"><span>${escapeHtml(document.category)} · ${escapeHtml(document.format)}</span><strong>${escapeHtml(document.title)}</strong><p>${escapeHtml(document.path)}</p><a href="${escapeHtml(document.url)}" target="_blank" rel="noopener">Open document ↗</a></article>`).join('')}
$('documentSearch').addEventListener('input',filterDocuments);$('documentCategory').addEventListener('change',filterDocuments);
function parseConversation(value){const names=[];return value.split(/\n+/).map(line=>line.trim()).filter(Boolean).map((line,index)=>{const match=line.match(/^([^:\n]{1,40})\s*:\s*(.+)$/);if(!match)throw new Error(`Line ${index+1} must use “Name: sentence”.`);const displaySpeaker=match[1].trim();let speaker;if(/^(oca|ocarina)$/i.test(displaySpeaker))speaker='Oca';else if(/^(orin|organ)$/i.test(displaySpeaker))speaker='Orin';else{const normalized=normalize(displaySpeaker);if(!names.includes(normalized))names.push(normalized);if(names.length>2)throw new Error('A performance may contain no more than two speakers.');speaker=names.indexOf(normalized)===0?'Oca':'Orin'}return{speaker,displaySpeaker,english:match[2],...CONVERSATION_SPEAKERS[speaker]}})}
function lorePresetByKey(value){const key=String(value||'').trim().toUpperCase();return(state.data?.lore_conversations?.presets||[]).find(preset=>preset.key===key||(preset.aliases||[]).includes(key))}
function renderLorePresetPicker(){const presets=state.data?.lore_conversations?.presets||[];$('lorePresetSelect').innerHTML='<option value="">Choose a lore moment</option>'+presets.map(preset=>`<option value="${escapeHtml(preset.key)}">${escapeHtml(preset.story)} — ${escapeHtml(preset.title)}</option>`).join('')}
function renderLorePresetDetail(preset){const detail=$('lorePresetDetail');if(!preset){detail.classList.add('hidden');detail.innerHTML='';return}detail.classList.remove('hidden');detail.innerHTML=`<header><span class="lore-key">${escapeHtml(preset.key)}</span><h4>${escapeHtml(preset.title)}</h4></header><p><b>${escapeHtml(preset.story)}</b> · ${escapeHtml(preset.era)} — ${escapeHtml(preset.explanation)}</p><blockquote>${preset.source_excerpt.map(line=>`<p>${escapeHtml(line)}</p>`).join('')}</blockquote><p class="lore-source">Source: ${escapeHtml(preset.source_path)} · ${escapeHtml(preset.source_section)}</p><p class="lore-note"><b>What the performance preserves:</b> ${escapeHtml(preset.performance_note)}</p>`}
async function loadLorePreset(value=null){const key=value||$('lorePresetKey').value||$('lorePresetSelect').value,preset=lorePresetByKey(key);if(!preset){$('conversationStatus').textContent='That lore key was not found. Choose a listed moment or check the key.';return}state.activeLorePreset=preset;$('lorePresetSelect').value=preset.key;$('lorePresetKey').value=preset.key;$('conversationScript').value=preset.performance_turns.map(turn=>`${turn.speaker}: ${turn.english}`).join('\n');renderLorePresetDetail(preset);await buildConversation()}
function conversationTargets(english){const targets=[],warnings=[];for(const sentence of english.split(/(?<=[.!?])\s+/).filter(Boolean)){const result=analyzeEnglish(sentence,state.data);for(const item of result.term_coverage||[]){if(item.status==='canonical'){const match=item.matches.find(candidate=>DIRECT.has(candidate.route)&&candidate.target_id&&state.data.resolution_files[candidate.target_id]);if(match)targets.push({target_id:match.target_id,term:item.term,sense_key:match.sense_key})}else if(['unresolved_semantic','documented_gap','structural'].includes(item.status))warnings.push(`${item.term}: ${item.status.replaceAll('_',' ')}`)}}return{targets,warnings}}
async function buildConversation(){const button=$('buildConversation');button.disabled=true;try{const turns=parseConversation($('conversationScript').value);for(const turn of turns){const mapped=conversationTargets(turn.english);turn.targets=mapped.targets;turn.warnings=mapped.warnings;turn.formals=[];for(const target of turn.targets){const document=await resolutionDocument(target.target_id);turn.formals.push(document.variants['assertion:1'].formal)}}state.conversation=turns;renderConversation();const playable=turns.some(turn=>turn.formals.length);$('playConversation').disabled=!playable;$('conversationStatus').textContent=`Translated ${turns.length} turn${turns.length===1?'':'s'} · ${turns.reduce((sum,turn)=>sum+turn.formals.length,0)} approved concept performances${turns.some(turn=>turn.warnings.length)?' · review the visible limitations below':''}.`}catch(error){state.conversation=[];$('playConversation').disabled=true;$('conversationStatus').textContent=error.message||'The conversation could not be translated.'}finally{button.disabled=false}}
function renderConversation(){const box=$('conversationTurns');box.innerHTML=state.conversation.map((turn,index)=>`<article class="conversation-turn" data-turn="${index}" data-speaker="${turn.speaker}"><header><strong>${escapeHtml(turn.displaySpeaker||turn.speaker)}</strong><span>${turn.label}</span></header><p>${escapeHtml(turn.english)}</p><code>${turn.targets.map(target=>escapeHtml(target.target_id)).join(' · ')||'No playable canonical concepts'}</code>${turn.targets.length?`<div class="turn-meaning">${turn.targets.map(target=>`${escapeHtml(target.term)} → ${escapeHtml(target.target_id)}`).join(' · ')}</div>`:''}${turn.warnings.length?`<div class="turn-warning">Not sounded: ${escapeHtml(turn.warnings.join(' · '))}</div>`:''}</article>`).join('')}
$('lorePresetSelect').addEventListener('change',event=>{if(event.target.value){$('lorePresetKey').value=event.target.value;loadLorePreset(event.target.value)}});
