$('verifyPerformanceMidi').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(!state.resolution)throw new Error('Resolve a meaning before checking a performance.');const result=verifyPerformanceMidi(state.resolution.formal,state.data.recognition_audio,await file.arrayBuffer());$('performanceCheck').textContent=result.status==='valid_checksum'?`Verified optional identity phrase · ${result.observed_note_count} notes · no semantic change.`:result.status==='valid_strict_absence'?`Verified strict canonical notes without an identity phrase · ${result.observed_note_count} notes.`:`Performance mismatch at note ${result.first_mismatch+1}; expected ${result.expected_note_count} notes, heard ${result.observed_note_count}. No meaning was inferred.`;toast(result.status.replaceAll('_',' '))}catch(error){$('performanceCheck').textContent=`Could not verify performance: ${error.message}`;toast(error.message)}finally{event.target.value=''}});
$('downloadPerformanceWav').addEventListener('click',()=>{if(!state.resolution)return toast('Resolve a meaning before exporting.');const mode=currentSoundMode(),bytes=wavFromPerformance(state.resolution.formal,state.data.recognition_audio,mode);download(new Blob([bytes],{type:'audio/wav'}),`era-zero-${mode}-reference.wav`)});
$('selfCheckAudio').addEventListener('click',async()=>{if(!state.resolution)return toast('Resolve a meaning before checking audio.');const Engine=window.AudioContext||window.webkitAudioContext;if(!Engine)return toast('Web Audio decoding is unavailable.');let context=null;try{context=new Engine();const bytes=wavFromPerformance(state.resolution.formal,state.data.recognition_audio,currentSoundMode()),decoded=await context.decodeAudioData(bytes.buffer.slice(0)),result=verifyPerformancePcm(state.resolution.formal,state.data.recognition_audio,decoded.getChannelData(0),decoded.sampleRate);$('audioCheck').textContent=result.status==='valid_checksum'?`Browser self-check passed: identity phrase and ${result.observed_note_count} notes verified.`:result.status==='valid_strict_absence'?`Browser self-check passed: strict canonical notes verified with no identity phrase.`:`Browser self-check failed at note ${result.first_mismatch+1}.`;toast(result.status.replaceAll('_',' '))}catch(error){$('audioCheck').textContent=`Browser self-check failed: ${error.message}`;toast(error.message)}finally{if(context)await context.close()}});
$('verifyPerformanceAudio').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;let context=null;try{if(!state.resolution)throw new Error('Resolve a meaning before checking audio.');if(file.size>20_000_000)throw new Error('Audio file is too large for this browser check.');const Engine=window.AudioContext||window.webkitAudioContext;if(!Engine)throw new Error('Web Audio decoding is unavailable.');context=new Engine();const decoded=await context.decodeAudioData(await file.arrayBuffer()),samples=new Float32Array(decoded.length);for(let channel=0;channel<decoded.numberOfChannels;channel++){const source=decoded.getChannelData(channel);for(let i=0;i<samples.length;i++)samples[i]+=source[i]/decoded.numberOfChannels}const result=verifyPerformancePcm(state.resolution.formal,state.data.recognition_audio,samples,decoded.sampleRate);$('audioCheck').textContent=result.status==='valid_checksum'?`Audio verified: optional identity phrase matches · ${result.observed_note_count} notes.`:result.status==='valid_strict_absence'?`Audio verified: canonical strict notes with no identity phrase · ${result.observed_note_count} notes.`:`Audio did not match this canonical form at note ${result.first_mismatch+1}; detected ${result.observed_note_count} notes. No meaning inferred.`;toast(result.status.replaceAll('_',' '))}catch(error){$('audioCheck').textContent=`Audio check inconclusive: ${error.message}`;toast(error.message)}finally{if(context)await context.close();event.target.value=''}});
$('downloadViseme').addEventListener('click',()=>{if(!state.resolution)return toast('Resolve a meaning before exporting its visemes.');const file=visemeFileFromFormal(state.resolution.formal,currentEyeExpression,recognitionOptions());download(new Blob([JSON.stringify(file,null,2)],{type:'application/json'}),`${state.resolution.formal.formal_id.toLowerCase().replace(':','-')}-${currentEyeExpression}.ezviseme.json`)});
