function showPlaying(button,durationMs,label){if(!button)return;const original=button.textContent;button.disabled=true;button.textContent=`♪ Playing ${label}`;setTimeout(()=>{button.disabled=false;button.textContent=original},durationMs)}
async function playName(name,button=null){try{const{context,bus}=await readyAudio();let at=context.currentTime+.08;const notes=notesForName(name);notes.forEach((note,index)=>{const frame=index<3||index>=notes.length-3,duration=frame?.24:.34;playScheduledTone(context,bus,note,at,{frame,duration});at+=duration+.055});const durationMs=Math.ceil((at-context.currentTime+.1)*1000);showPlaying(button,durationMs,'phoneme tones…');toast(`Audio started · ${notes.length} phoneme-label tones.`)}catch(error){toast(error.message||'Audio could not start. Check the tab and system volume, then try again.')}}
async function playPhraseNames(button=null){if(!state.phraseNames.length)return;try{const{context,bus}=await readyAudio();let at=context.currentTime+.08,total=0;state.phraseNames.forEach(name=>{const notes=notesForName(name);total+=notes.length;notes.forEach((note,index)=>{const frame=index<3||index>=notes.length-3,duration=frame?.21:.30;playScheduledTone(context,bus,note,at,{frame,duration});at+=duration+.045});at+=.18});const durationMs=Math.ceil((at-context.currentTime+.1)*1000);showPlaying(button,durationMs,'phrase labels…');toast(`Audio started · ${total} tones across ${state.phraseNames.length} unfamiliar term${state.phraseNames.length===1?'':'s'}.`)}catch(error){toast(error.message||'Audio could not start. Check the tab and system volume, then try again.')}}
