$('soundMode').addEventListener('change',event=>{const descriptions={recognition:'Adds an optional identity checksum; meaning and grammar stay unchanged.',strict:'Plays only the canonical family, address, runtime, and contour notes.',learning:'Plays the same checksum more slowly for recognition practice.'};$('soundModeDescription').textContent=descriptions[event.target.value];localStorage.setItem('era-zero-sound-mode',event.target.value);if(state.resolution)showResolution(state.resolution,state.selected);toast(`${event.target.options[event.target.selectedIndex].text} selected.`)});
$('phonemeHelp').textContent=`Editable sound symbols: ${PHONEMES.join(' ')}`;
const savedVoice=localStorage.getItem('era-zero-sound-voice');if(savedVoice&&VOICE_PROFILES[savedVoice]){$('soundVoice').value=savedVoice;$('soundVoiceDescription').textContent=VOICE_PROFILES[savedVoice].description}
const savedSoundMode=localStorage.getItem('era-zero-sound-mode');if(['strict','recognition','learning'].includes(savedSoundMode))$('soundMode').value=savedSoundMode;
$('conversationScript').value=DEMO_CONVERSATION;
boot();
